window.RP_SESSION={"id":"S-61b494662897","messages":[{"id":"RP-0268497","time":"2026-09-09T20:34:00+09:00","room":"RP","name":"헥터","profile":"헥터","identity":"unresolved","type":"dialogue","body":"그녀는 한잔의 술을 마시며\n연구를 계속했다.\n\n술이란 그녀의 뇌에 보내는 활력제,\n그 짜릿한 입맞춤이 뇌를 번뜩였다.\n.\n.\n시간이 얼마나 지났을까.\n잔은 비워졌고, 책속은 글과 그림으로 빽빽하게 채워졌다.\n\n냉기 마법과 전격 마법의 융합 그 효율에 대하여...\n그녀가 계속해서 연구하는 목표중 하나였다.\n\n허나 잔이 비워져서일까, 그녀의 머릿속에서도 슬슬 지식의 갈증이 시작되었다.\n\n아아 어찌그리 복잡하단 말인가..!\n뇌속이 뒤집힐것 같다.\n숙취가 오듯이 그녀의 뇌가 끊임없이 그녀를 어지럽게 하였다.\n\n그녀는 그 순간 연구를 멈추고 비워진 잔을 그대로 놓고 강가로 가 몸을 젖히고 젖혀 강가의 찬물로 정신을 일깨웠다.","characters":[]},{"id":"RP-0268498","time":"2026-09-09T20:36:00+09:00","room":"RP","name":"헥터","profile":"헥터","identity":"unresolved","type":"dialogue","body":"-fin","characters":[]},{"id":"RP-0268499","time":"2026-09-09T20:36:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"... 계속.","characters":[]},{"id":"RP-0268500","time":"2026-09-09T22:55:00+09:00","room":"RP","name":"하일로 조바","profile":"하일로 조바","identity":"unresolved","type":"dialogue","body":"!모닥불","characters":[]},{"id":"RP-0268501","time":"2026-09-09T22:55:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"모닥불에 불씨가 옮겨 붙습니다.\n따뜻한 온기가 피어오릅니다.\n\n ♩ https://youtu.be/3GNyTB6p6i0?si=4L6Rg34M-gtWRqUj","characters":[]}]};
